def convert_list_dictionary(*lists):
    if not lists:
        return {}

    num_lists = len(lists)

    # If there are fewer than two lists, a key-value pair structure cannot be formed.
    # A nested dictionary typically requires at least three lists (key1, key2, value).
    # If only two lists are provided, it forms a flat dictionary.
    # If only one list is provided, it cannot form a dictionary of keys and values.
    if num_lists < 2: 
        return {}

