    # This prevents IndexError if lists have different lengths.
    length = min(len(lst) for lst in lists)

    result_dict = {}

    for i in range(length):
        current_dict = result_dict

        # Iterate through the lists that provide keys for nesting levels.
        # This loop goes from the first list (index 0) up to the second-to-last list (index num_lists - 2).
        # The last list (index num_lists - 1) contains the final values.
        # The second-to-last list (index num_lists - 2) contains the keys for the innermost dictionary.
        for j in range(num_lists - 2): 
