def radix_sort(nums):
    if not nums:
        return nums

    RADIX = 10
    placement = 1
    max_val = max(nums)

    while placement <= max_val:
        buckets = [list() for _ in range(RADIX)]
        for i in nums:
            digit = int((i / placement) % RADIX)
            buckets[digit].append(i)

        a = 0
        for b in range(RADIX):
            buck = buckets[b]
            for i in buck:
                nums[a] = i
                a += 1
        placement *= RADIX
    return nums

